<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Conway's Game of Life</title>
<style>
  :root {
    --bg: #121212;
    --surface: #1e1e1e;
    --accent: #00d4ff;
    --text: #e0e0e0;
    --grid-line: #222;
  }
  body {
    background: var(--bg);
    color: var(--text);
    font-family: system-ui, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    margin: 0;
    user-select: none;
  }
  h1 {
    margin: 10px 0 20px;
    font-size: 1.5rem;
    color: var(--accent);
  }
  #life {
    border: 2px solid #333;
    background: #000;
    image-rendering: pixelated;
    box-shadow: 0 4px 20px rgba(0,0,0,0.5);
    touch-action: none;
  }
  .controls {
    margin-top: 16px;
    display: flex;
    gap: 10px;
  }
  button {
    background: var(--surface);
    color: var(--text);
    border: 1px solid #444;
    padding: 8px 16px;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 600;
    font-size: 0.9rem;
    transition: all 0.2s ease;
  }
  button:hover {
    border-color: var(--accent);
    color: var(--accent);
  }
  button:active {
    transform: translateY(1px);
  }
  button.playing {
    background: var(--accent);
    color: #000;
    border-color: var(--accent);
  }
</style>
</head>
<body>

<h1>Game of Life</h1>
<canvas id="life"></canvas>
<div class="controls">
  <button id="step">Step</button>
  <button id="play">Play</button>
  <button id="random">Random</button>
  <button id="clear">Clear</button>
</div>

<script>
const canvas = document.getElementById('life');
const ctx = canvas.getContext('2d', { alpha: false });
const ROWS = 40;
const COLS = 40;
const CELL_SIZE = 15;

canvas.width = COLS * CELL_SIZE;
canvas.height = ROWS * CELL_SIZE;

let grid = new Array(ROWS).fill(0).map(() => new Array(COLS).fill(0));
let nextGrid = new Array(ROWS).fill(0).map(() => new Array(COLS).fill(0));
let isPlaying = false;
let timer = null;

// Initialize grid with random values
function randomize() {
  for (let y = 0; y < ROWS; y++) {
    for (let x = 0; x < COLS; x++) {
      grid[y][x] = Math.random() < 0.5 ? 1 : 0;
    }
  }
  draw();
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw living cells
  ctx.fillStyle = '#00d4ff';
  for (let y = 0; y < ROWS; y++) {
    for (let x = 0; x < COLS; x++) {
      if (grid[y][x]) {
        ctx.fillRect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
      }
    }
  }

  // Draw grid lines
  ctx.strokeStyle = '#222';
  ctx.lineWidth = 1;
  ctx.beginPath();
  for (let i = 0; i <= COLS; i++) {
    const x = i * CELL_SIZE;
    ctx.moveTo(x, 0);
    ctx.lineTo(x, canvas.height);
  }
  for (let i = 0; i <= ROWS; i++) {
    const y = i * CELL_SIZE;
    ctx.moveTo(0, y);
    ctx.lineTo(canvas.width, y);
  }
  ctx.stroke();
}

function countNeighbors(x, y) {
  let count = 0;
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      if (dx === 0 && dy === 0) continue;
      const nx = x + dx;
      const ny = y + dy;
      if (nx >= 0 && ny >= 0 && nx < COLS && ny < ROWS && grid[ny][nx]) {
        count++;
      }
    }
  }
  return count;
}

// API
window.life = {
  w: COLS,
  h: ROWS,
  get(x, y) {
    if (x < 0 || y < 0 || x >= COLS || y >= ROWS) return 0;
    return grid[y][x] ? 1 : 0;
  },
  set(x, y, v) {
    if (x >= 0 && y >= 0 && x < COLS && y < ROWS) {
      grid[y][x] = v ? 1 : 0;
      draw();
    }
  },
  step() {
    for (let y = 0; y < ROWS; y++) {
      for (let x = 0; x < COLS; x++) {
        const neighbors = countNeighbors(x, y);
        const cell = grid[y][x];
        if (cell) {
          nextGrid[y][x] = (neighbors === 2 || neighbors === 3) ? 1 : 0;
        } else {
          nextGrid[y][x] = (neighbors === 3) ? 1 : 0;
        }
      }
    }
    [grid, nextGrid] = [nextGrid, grid];
    draw();
  },
  clear() {
    for (let y = 0; y < ROWS; y++) {
      for (let x = 0; x < COLS; x++) {
        grid[y][x] = 0;
      }
    }
    draw();
  }
};

// Controls
document.getElementById('step').onclick = () => {
  if (isPlaying) togglePlay();
  window.life.step();
};

function togglePlay() {
  isPlaying = !isPlaying;
  const btn = document.getElementById('play');
  if (isPlaying) {
    btn.classList.add('playing');
    timer = setInterval(() => window.life.step(), 100);
  } else {
    btn.classList.remove('playing');
    clearInterval(timer);
  }
}

document.getElementById('play').onclick = togglePlay;

document.getElementById('random').onclick = () => {
  randomize();
};

document.getElementById('clear').onclick = () => {
  if (isPlaying) togglePlay();
  window.life.clear();
};

// Interaction
let isDrawing = false;

function getPos(e) {
  const rect = canvas.getBoundingClientRect();
  const clientX = e.touches ? e.touches[0].clientX : e.clientX;
  const clientY = e.touches ? e.touches[0].clientY : e.clientY;
  return {
    x: Math.floor((clientX - rect.left) / CELL_SIZE),
    y: Math.floor((clientY - rect.top) / CELL_SIZE)
  };
}

function toggleCell(e) {
  const { x, y } = getPos(e);
  if (x >= 0 && x < COLS && y >= 0 && y < ROWS) {
    grid[y][x] = grid[y][x] ? 0 : 1;
    draw();
  }
}

canvas.addEventListener('mousedown', (e) => { isDrawing = true; toggleCell(e); });
canvas.addEventListener('mousemove', (e) => { if (isDrawing) toggleCell(e); });
canvas.addEventListener('mouseup', () => { isDrawing = false; });
canvas.addEventListener('mouseleave', () => { isDrawing = false; });

canvas.addEventListener('touchstart', (e) => { isDrawing = true; toggleCell(e); }, { passive: false });
canvas.addEventListener('touchmove', (e) => { if (isDrawing) e.preventDefault(); toggleCell(e); }, { passive: false });
canvas.addEventListener('touchend', () => { isDrawing = false; });

draw();
</script>
</body>
</html>
